CREATE TABLE trades_2026_04
PARTITION OF trades
FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');

CREATE TABLE trades_2026_05
PARTITION OF trades
FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');

CREATE TABLE trades_2026_06
PARTITION OF trades
FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');

CREATE TABLE trades_2026_07
PARTITION OF trades
FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');

CREATE TABLE trades_default
PARTITION OF trades
DEFAULT;

CREATE INDEX idx_trades_partitioned_status
    ON trades(status);

CREATE INDEX idx_trades_partitioned_instrument_id
    ON trades(instrument_id);

CREATE INDEX idx_trades_partitioned_counterparty_id
    ON trades(counterparty_id);

INSERT INTO trades
SELECT *
FROM trades_legacy;
